import os, pty, termios, fcntl, struct, subprocess, select, time, tempfile, pathlib, json, re, unicodedata, signal
repo = pathlib.Path.cwd()
def screen(data):
    cells = [[' '] * 140 for _ in range(30)]
    x = y = 0
    for token in re.finditer(r'\x1b\[([0-?]*)([ -/]*)([@-~])|([^\x1b])', data.decode('utf-8', 'replace')):
        if token[3]:
            params = token[1].lstrip('?')
            values = [int(part or '0') for part in params.split(';')] if params else [0]
            n = values[0] or 1; command = token[3]
            if command in ('H','f'):
                y = max(0,n-1); x = max(0,(values[1] if len(values)>1 and values[1] else 1)-1)
            elif command == 'G': x = max(0,n-1)
            elif command == 'd': y = max(0,n-1)
            elif command == 'A': y = max(0,y-n)
            elif command == 'B': y += n
            elif command == 'C': x += n
            elif command == 'D': x = max(0,x-n)
            elif command == 'J' and values[0] in (2,3): cells = [[' ']*140 for _ in range(30)]
            elif command == 'K' and 0<=y<30:
                left,right = (0,140) if values[0]==2 else ((0,min(x+1,140)) if values[0]==1 else (min(x,140),140))
                for column in range(left,right): cells[y][column]=' '
        elif token[4] == '\r': x=0
        elif token[4] == '\n': y+=1
        elif token[4].isprintable():
            width=2 if unicodedata.east_asian_width(token[4]) in ('W','F') else 1
            if 0<=x<140 and 0<=y<30:
                old=cells[y][x]
                cells[y][x]=token[4]
                if width==2 and x+1<140: cells[y][x+1]=''
                elif old and unicodedata.east_asian_width(old) in ('W','F') and x+1<140: cells[y][x+1]=' '
            x+=width
    return '\n'.join(''.join(row) for row in cells)

assert screen('\x1b[1;1H检验内容\x1b[1;1H候选 3\x1b[K'.encode()).splitlines()[0].strip() == '候选 3'
